import{_ as o,o as r,c as a,ag as e}from"./chunks/framework.QfQ7DfGu.js";const u=JSON.parse('{"title":"LA资源总览","description":"","frontmatter":{"title":"LA资源总览","outline":"deep"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(t,l,h,p,g,c){return r(),a("div",null,[...l[0]||(l[0]=[e('<h1 id="龙架构核心系统能力资源" tabindex="-1">龙架构核心系统能力资源 <a class="header-anchor" href="#龙架构核心系统能力资源" aria-label="Permalink to &quot;龙架构核心系统能力资源&quot;">​</a></h1><p>站内主要入口汇总</p><h2 id="教学资源" tabindex="-1"><strong>教学资源</strong> <a class="header-anchor" href="#教学资源" aria-label="Permalink to &quot;**教学资源**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/resources/courses/intro/">计算机系统</a></p><p>主要包括一些课程的视频、课件及其实验代码等：</p><ul><li>《计算机体系结构》—— 袁春风、鲍培明</li><li>《计算机系统实践教程》—— 袁春风、鲍培明</li></ul></li><li><p><a href="/loongarch-learning/resources/courses/arch/">组成原理/体系结构</a></p><p>主要包括一些课程的视频、课件及其实验代码等，另外包括一些教材，参考书籍等：</p><ul><li>《计算机体系结构十讲》—— 胡伟武</li><li>《计算机体系结构六讲》—— 胡伟武</li><li>《龙架构体系结构实验课》—— 胡伟武</li></ul><p>一些书籍与参考资料：</p><ul><li>《计算机体系结构基础》—— 胡伟武、汪文祥等</li><li>《CPU设计实战：LoongArch版》—— 汪文祥、邢金璋</li></ul></li><li><p><a href="/loongarch-learning/resources/courses/os/">操作系统</a></p><p>主要包括一些课程的视频、课件、教材及其实验代码等：</p><ul><li>《深入理解操作系统》—— 宫晓利</li><li>《操作系统设计与实现（基于 LoongArch 架构）》—— 周庆国</li><li>《操作系统内核构建》—— 张羽、郭琼、张福新等</li></ul></li><li><p><a href="/loongarch-learning/resources/courses/compiler/">编译原理</a></p><p>主要包括一些课程的视频、课件、教材及其实验代码等：</p><ul><li>《编译系统设计与实现》—— 李诚</li></ul></li></ul><h2 id="竞赛资源" tabindex="-1"><strong>竞赛资源</strong> <a class="header-anchor" href="#竞赛资源" aria-label="Permalink to &quot;**竞赛资源**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/competitions/os-design/">操作系统设计赛</a></p><p>有关往年的操作系统相关内容：</p><ul><li>往年的比赛的OS Kernel</li><li>往年比赛的优秀作品</li><li>往年比赛的报告</li><li>往年问题的FAQ</li></ul></li><li><p><a href="/loongarch-learning/competitions/compiler-design/">编译系统设计赛</a></p><p>有关往年的编译相关内容：</p><ul><li>往年的比赛的优秀作品</li><li>往年比赛的报告</li><li>往年问题的FAQ</li></ul></li></ul><h2 id="龙架构相关文档" tabindex="-1"><strong>龙架构相关文档</strong> <a class="header-anchor" href="#龙架构相关文档" aria-label="Permalink to &quot;**龙架构相关文档**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/docs-la/">官方参考手册</a></p><p>主要涉及于龙架构相关的一些开发手册</p><ul><li>龙芯架构参考手册 卷一：基础架构（64位/32位）</li><li>龙芯架构32位精简版参考手册（LoongArch32R）</li><li>应用程序二进制接口ABI-2.0</li><li>工具链规约手册</li><li>龙架构汇编语言编程手册-2024-10版本</li></ul><p><a href="/loongarch-learning/docs-la/others-ref.html">其他参考手册</a></p><ul><li>还要其他相关文档，具体可进入相关页查看</li></ul><p><a href="/loongarch-learning/docs-la/others-la64-insn.html">LoongArch64指令C语言实现</a></p><ul><li>模拟器实现了LoongArch64的相关指令</li><li>如果官方手册的指令描述不清楚，可查看相关的C实现</li></ul></li><li><p><a href="/loongarch-learning/practice/ip.html">LoongArch相关IP</a></p><p>主要涉及和龙架构相关的一些IP核：</p><ul><li>OpenC910：具有先进的12级流水线，乱序执行的超标量处理器</li><li>LabCore164：五级流水线，支持浮点</li><li>ChipLab：loongArch32R的一个实现SOC</li><li>Open-500：一个实现了LoongArch32R的五级流水</li></ul></li></ul><h2 id="loongarch-工具链" tabindex="-1"><strong>LoongArch 工具链</strong> <a class="header-anchor" href="#loongarch-工具链" aria-label="Permalink to &quot;**LoongArch 工具链**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/toolchain/compiler.html">LoongArch工具链</a></p><p>主要是涉及龙架构的交叉编译器：</p><ul><li>GCC与其GLIBC</li><li>GDB</li><li>QEMU模拟器</li><li>Clang编译器</li><li>Rust</li><li>Go</li><li>.NET等</li></ul></li><li><p><a href="/loongarch-learning/toolchain/libc.html">LIBC库</a>： 常用的C库：</p><ul><li>glibc</li><li>musl</li><li>newlib</li><li>piclic</li></ul></li><li><p><a href="/loongarch-learning/toolchain/linux-kernel.html">Linux内核</a></p></li><li><p><a href="/loongarch-learning/toolchain/uboot.html">U-boot</a></p></li><li><p><a href="/loongarch-learning/toolchain/uefi.html">UEFI</a></p></li></ul><h2 id="loongarch开发版" tabindex="-1"><strong>LoongArch开发版</strong> <a class="header-anchor" href="#loongarch开发版" aria-label="Permalink to &quot;**LoongArch开发版**&quot;">​</a></h2><p>涉及常用的开发版相关资料</p><ul><li><p><a href="/loongarch-learning/platform/2k1000la.html">2k1000LA星云板</a></p></li><li><p><a href="/loongarch-learning/platform/2k0300.html">2k0300蜂鸟</a></p></li><li><p><a href="/loongarch-learning/platform/2k3000.html">2k3000开发板</a></p></li></ul><h2 id="操作系统" tabindex="-1"><strong>操作系统</strong> <a class="header-anchor" href="#操作系统" aria-label="Permalink to &quot;**操作系统**&quot;">​</a></h2><p><a href="/loongarch-learning/os/release-os.html">支持龙架构的发行版</a></p><p><a href="/loongarch-learning/os/os-kernel.html">LoongArch开源Kernel</a></p><p><a href="/loongarch-learning/os/os-kernel.html">基于Rust的Kernel</a></p><h2 id="loongarch相关的仓库" tabindex="-1"><strong>LoongArch相关的仓库</strong> <a class="header-anchor" href="#loongarch相关的仓库" aria-label="Permalink to &quot;**LoongArch相关的仓库**&quot;">​</a></h2><p>龙芯实验室:<a href="https://github.com/LoongsonLab" target="_blank" rel="noreferrer">https://github.com/LoongsonLab</a></p><p>龙芯爱好者社区:<a href="https://www.loongbbs.cn/" target="_blank" rel="noreferrer">https://www.loongbbs.cn/</a></p><p>电子发烧友龙芯版块:<a href="https://bbs.elecfans.com/group_1650" target="_blank" rel="noreferrer">https://bbs.elecfans.com/group_1650</a></p><p>龙芯Loongnix系统:<a href="http://www.loongnix.cn/zh/proj/" target="_blank" rel="noreferrer">http://www.loongnix.cn/zh/proj/</a></p><p>龙芯应用合作社: <a href="https://app.loongapps.cn" target="_blank" rel="noreferrer">https://app.loongapps.cn</a></p><p>龙芯开源社区:<a href="http://www.loongnix.cn/zh/proj/" target="_blank" rel="noreferrer">http://www.loongnix.cn/zh/proj/</a></p><p>龙芯爱好者社区:<a href="https://www.loongbbs.cn/" target="_blank" rel="noreferrer">https://www.loongbbs.cn/</a></p><p>龙芯应用合作社: <a href="https://app.loongapps.cn/" target="_blank" rel="noreferrer">https://app.loongapps.cn/</a></p><p>龙芯开源组织:<a href="https://github.com/loongson" target="_blank" rel="noreferrer">https://github.com/loongson</a></p><p>龙芯云社区:<a href="https://github.com/Loongson-Cloud-Community" target="_blank" rel="noreferrer">https://github.com/Loongson-Cloud-Community</a></p><p>loong64: <a href="https://github.com/loong64" target="_blank" rel="noreferrer">https://github.com/loong64</a></p><p>龙芯开源组织: <a href="https://gitee.com/loongson" target="_blank" rel="noreferrer">https://gitee.com/loongson</a></p><p>开源鸿蒙龙架构移植: <a href="https://gitee.com/openharmony-loongarch" target="_blank" rel="noreferrer">https://gitee.com/openharmony-loongarch</a></p><p>龙芯教育:<a href="https://gitee.com/loongson-edu" target="_blank" rel="noreferrer">https://gitee.com/loongson-edu</a></p><p>loongson生态创新中心:<a href="https://gitee.com/cn-loongson" target="_blank" rel="noreferrer">https://gitee.com/cn-loongson</a></p><h2 id="资讯动态" tabindex="-1"><strong>资讯动态</strong> <a class="header-anchor" href="#资讯动态" aria-label="Permalink to &quot;**资讯动态**&quot;">​</a></h2><p>最近更新日期：2026-3-25</p><hr><p><a href="/loongarch-learning/feedback/">问题反馈</a></p>',37)])])}const f=o(n,[["render",i]]);export{u as __pageData,f as default};
